	local _cc_a
	for _cc_a in ${1+"$@"}
	do
		case "$_cc_a" in
			(-*-filter* | -*-pager* | -*-view* | -*-format-open* | -*-config* | ---* | -@* | -*-save-config* | -[Zz]* | -[!-]*[Zz]* | --null | --null-data) command grep ${1+"$@"}
				return ;;
		esac
	done
	local _cc_bin="${CLAUDE_CODE_EXECPATH:-}" 
	[[ -x $_cc_bin ]] || _cc_bin=/Users/allenjiang/.local/bin/claude 
	if [[ ! -x $_cc_bin ]]
	then
		command grep ${1+"$@"}
		return
	fi
	if [[ -n ${ZSH_VERSION:-} ]]
	then
		ARGV0=ugrep "$_cc_bin" -G --ignore-files --hidden -I --exclude-dir=.git --exclude-dir=.svn --exclude-dir=.hg --exclude-dir=.bzr --exclude-dir=.jj --exclude-dir=.sl ${1+"$@"}
	elif [[ "$OSTYPE" == "msys" ]] || [[ "$OSTYPE" == "cygwin" ]] || [[ "$OSTYPE" == "win32" ]]
	then
		ARGV0=ugrep "$_cc_bin" -G --ignore-files --hidden -I --exclude-dir=.git --exclude-dir=.svn --exclude-dir=.hg --exclude-dir=.bzr --exclude-dir=.jj --exclude-dir=.sl ${1+"$@"}
	else
		(
			exec -a ugrep "$_cc_bin" -G --ignore-files --hidden -I --exclude-dir=.git --exclude-dir=.svn --exclude-dir=.hg --exclude-dir=.bzr --exclude-dir=.jj --exclude-dir=.sl ${1+"$@"}
		)
	fi
}
