1	package com.bumptech.glide.load.data.mediastore;
2	
3	import android.content.ContentResolver;
4	import android.content.res.AssetFileDescriptor;
5	import android.net.Uri;
6	import android.os.Build;
7	import android.os.Build.VERSION_CODES;
8	import android.os.ext.SdkExtensions;
9	import android.provider.MediaStore;
10	import androidx.annotation.ChecksSdkIntAtLeast;
11	import androidx.annotation.RequiresExtension;
12	import com.bumptech.glide.request.target.Target;
13	import java.io.FileNotFoundException;
14	
15	/** Utility classes for interacting with the media store. */
16	public final class MediaStoreUtil {
17	  public static final int MIN_EXTENSION_VERSION_FOR_OPEN_FILE_APIS = 17;
18	  private static final int MINI_THUMB_WIDTH = 512;
19	  private static final int MINI_THUMB_HEIGHT = 384;
20	
21	  private MediaStoreUtil() {
22	    // Utility class.
23	  }
24	
25	  public static boolean isMediaStoreUri(Uri uri) {
26	    return uri != null
27	        && ContentResolver.SCHEME_CONTENT.equals(uri.getScheme())
28	        && MediaStore.AUTHORITY.equals(uri.getAuthority());
29	  }
30	
31	  @ChecksSdkIntAtLeast(api = MIN_EXTENSION_VERSION_FOR_OPEN_FILE_APIS, extension = VERSION_CODES.R)
32	  public static boolean isMediaStoreOpenFileApisAvailable() {
33	    return Build.VERSION.SDK_INT >= Build.VERSION_CODES.R
34	        && SdkExtensions.getExtensionVersion(Build.VERSION_CODES.R)
35	            >= MIN_EXTENSION_VERSION_FOR_OPEN_FILE_APIS;
36	  }
37	
38	  @RequiresExtension(
39	      extension = VERSION_CODES.R,
40	      version = MIN_EXTENSION_VERSION_FOR_OPEN_FILE_APIS)
41	  public static AssetFileDescriptor openAssetFileDescriptor(
42	      Uri uri, ContentResolver contentResolver) throws FileNotFoundException {
43	    return MediaStore.openAssetFileDescriptor(contentResolver, uri, "r", null);
44	  }
45	
46	  /**
47	   * Android picker URIs contain a "picker" prefix in one of their path segments.
48	   * https://android.googlesource.com/platform/packages/providers/MediaProvider/+/refs/heads/master/src/com/android/providers/media/PickerUriResolver.java#58
49	   *
50	   * @deprecated This method is retained solely to support existing use cases. It should not be
51	   *     utilized for new development or upcoming features.
52	   */
53	  @Deprecated
54	  public static boolean isAndroidPickerUri(Uri uri) {
55	    if (!isMediaStoreUri(uri)) {
56	      return false;
57	    }
58	    for (String segment : uri.getPathSegments()) {
59	      if (segment != null && segment.startsWith("picker")) {
60	        return true;
61	      }
62	    }
63	    return false;
64	  }
65	
66	  private static boolean isVideoUri(Uri uri) {
67	    return uri.getPathSegments().contains("video");
68	  }
69	
70	  public static boolean isMediaStoreVideoUri(Uri uri) {
71	    return isMediaStoreUri(uri) && isVideoUri(uri);
72	  }
73	
74	  public static boolean isMediaStoreImageUri(Uri uri) {
75	    return isMediaStoreUri(uri) && !isVideoUri(uri);
76	  }
77	
78	  public static boolean isThumbnailSize(int width, int height) {
79	    return width != Target.SIZE_ORIGINAL
80	        && height != Target.SIZE_ORIGINAL
81	        && width <= MINI_THUMB_WIDTH
82	        && height <= MINI_THUMB_HEIGHT;
83	  }
84	}
