1	package com.bumptech.glide.manager;
2	
3	import android.util.Log;
4	import androidx.annotation.NonNull;
5	import androidx.annotation.Nullable;
6	import androidx.annotation.VisibleForTesting;
7	import com.bumptech.glide.request.Request;
8	import com.bumptech.glide.util.Util;
9	import java.util.Collections;
10	import java.util.HashSet;
11	import java.util.Set;
12	import java.util.WeakHashMap;
13	
14	/**
15	 * A class for tracking, canceling, and restarting in progress, completed, and failed requests.
16	 *
17	 * <p>This class is not thread safe and must be accessed on the main thread.
18	 */
19	public class RequestTracker {
20	  private static final String TAG = "RequestTracker";
21	  // Most requests will be for views and will therefore be held strongly (and safely) by the view
22	  // via the tag. However, a user can always pass in a different type of target which may end up not
23	  // being strongly referenced even though the user still would like the request to finish. Weak
24	  // references are therefore only really functional in this context for view targets. Despite the
25	  // side affects, WeakReferences are still essentially required. A user can always make repeated
26	  // requests into targets other than views, or use an activity manager in a fragment pager where
27	  // holding strong references would steadily leak bitmaps and/or views.
28	  private final Set<Request> requests =
29	      Collections.newSetFromMap(new WeakHashMap<Request, Boolean>());
30	  // A set of requests that have not completed and are queued to be run again. We use this list to
31	  // maintain hard references to these requests to ensure that they are not garbage collected
32	  // before they start running or while they are paused. See #346.
33	  private final Set<Request> pendingRequests = new HashSet<>();
34	
35	  private boolean isPaused;
36	
37	  /** Starts tracking the given request. */
38	  public void runRequest(@NonNull Request request) {
39	    requests.add(request);
40	    if (!isPaused) {
41	      request.begin();
42	    } else {
43	      request.clear();
44	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
45	        Log.v(TAG, "Paused, delaying request");
46	      }
47	      pendingRequests.add(request);
48	    }
49	  }
50	
51	  @VisibleForTesting
52	  void addRequest(Request request) {
53	    requests.add(request);
54	  }
55	
56	  /**
57	   * Stops tracking the given request, clears, and recycles it, and returns {@code true} if the
58	   * request was removed or invalid or {@code false} if the request was not found.
59	   */
60	  public boolean clearAndRemove(@Nullable Request request) {
61	    if (request == null) {
62	      // If the Request is null, the request is already cleared and we don't need to search further
63	      // for its owner.
64	      return true;
65	    }
66	    boolean isOwnedByUs = requests.remove(request);
67	    // Avoid short circuiting.
68	    isOwnedByUs = pendingRequests.remove(request) || isOwnedByUs;
69	    if (isOwnedByUs) {
70	      request.clear();
71	    }
72	    return isOwnedByUs;
73	  }
74	
75	  /** Returns {@code true} if requests are currently paused, and {@code false} otherwise. */
76	  public boolean isPaused() {
77	    return isPaused;
78	  }
79	
80	  /** Stops any in progress requests. */
81	  public void pauseRequests() {
82	    isPaused = true;
83	    for (Request request : Util.getSnapshot(requests)) {
84	      if (request.isRunning()) {
85	        // Avoid clearing parts of requests that may have completed (thumbnails) to avoid blinking
86	        // in the UI, while still making sure that any in progress parts of requests are immediately
87	        // stopped.
88	        request.pause();
89	        pendingRequests.add(request);
90	      }
91	    }
92	  }
93	
94	  /** Stops any in progress requests and releases bitmaps associated with completed requests. */
95	  public void pauseAllRequests() {
96	    isPaused = true;
97	    for (Request request : Util.getSnapshot(requests)) {
98	      // TODO(judds): Failed requests return false from isComplete(). They're still restarted in
99	      //  resumeRequests, but they're not cleared here. We should probably clear all requests here?
100	      if (request.isRunning() || request.isComplete()) {
101	        request.clear();
102	        pendingRequests.add(request);
103	      }
104	    }
105	  }
106	
107	  /** Starts any not yet completed or failed requests. */
108	  public void resumeRequests() {
109	    isPaused = false;
110	    for (Request request : Util.getSnapshot(requests)) {
111	      // We don't need to check for cleared here. Any explicit clear by a user will remove the
112	      // Request from the tracker, so the only way we'd find a cleared request here is if we cleared
113	      // it. As a result it should be safe for us to resume cleared requests.
114	      if (!request.isComplete() && !request.isRunning()) {
115	        request.begin();
116	      }
117	    }
118	    pendingRequests.clear();
119	  }
120	
121	  /**
122	   * Cancels all requests and clears their resources.
123	   *
124	   * <p>After this call requests cannot be restarted.
125	   */
126	  public void clearRequests() {
127	    for (Request request : Util.getSnapshot(requests)) {
128	      // It's unsafe to recycle the Request here because we don't know who might else have a
129	      // reference to it.
130	      clearAndRemove(request);
131	    }
132	    pendingRequests.clear();
133	  }
134	
135	  /** Restarts failed requests and cancels and restarts in progress requests. */
136	  public void restartRequests() {
137	    for (Request request : Util.getSnapshot(requests)) {
138	      if (!request.isComplete() && !request.isCleared()) {
139	        request.clear();
140	        if (!isPaused) {
141	          request.begin();
142	        } else {
143	          // Ensure the request will be restarted in onResume.
144	          pendingRequests.add(request);
145	        }
146	      }
147	    }
148	  }
149	
150	  @Override
151	  public String toString() {
152	    return super.toString() + "{numRequests=" + requests.size() + ", isPaused=" + isPaused + "}";
153	  }
154	}
