186	
187	      errorState = RequestState.FAILED;
188	
189	      if (parent != null) {
190	        parent.onRequestFailed(this);
191	      }
192	    }
193	  }
194	
195	  @Override
196	  public RequestCoordinator getRoot() {
197	    synchronized (requestLock) {
198	      return parent != null ? parent.getRoot() : this;
199	    }
200	  }
201	}
