98	    }
99	
100	    try {
101	      return context.createPackageContext(packageName, /* flags= */ 0);
102	    } catch (NameNotFoundException e) {
103	      // The parent APK holds the correct context if the resource is located in a split
104	      if (packageName.contains(context.getPackageName())) {
