113	  @DrawableRes
114	  private int findResourceIdFromUri(Context context, Uri source) {
115	    List<String> segments = source.getPathSegments();
116	    if (segments.size() == NAME_URI_PATH_SEGMENTS) {
117	      return findResourceIdFromTypeAndNameResourceUri(context, source);
118	    } else if (segments.size() == ID_PATH_SEGMENTS) {
119	      return findResourceIdFromResourceIdUri(source);
