125	  // android.resource://com.android.camera2/mipmap/logo_camera_color
126	  @DrawableRes
127	  private int findResourceIdFromTypeAndNameResourceUri(Context context, Uri source) {
128	    List<String> segments = source.getPathSegments();
129	    String packageName = source.getAuthority();
130	    String typeName = segments.get(TYPE_PATH_SEGMENT_INDEX);
131	    String resourceName = segments.get(NAME_PATH_SEGMENT_INDEX);
132	    int result = context.getResources().getIdentifier(resourceName, typeName, packageName);
133	    if (result == MISSING_RESOURCE_ID) {
134	      result = Resources.getSystem().getIdentifier(resourceName, typeName, ANDROID_PACKAGE_NAME);
135	    }
136	    if (result == MISSING_RESOURCE_ID) {
137	      throw new IllegalArgumentException("Failed to find resource id for: " + source);
138	    }
139	    return result;
140	  }
141	
142	  // android.resource://com.android.camera2/123456
143	  @DrawableRes
144	  private int findResourceIdFromResourceIdUri(Uri source) {
145	    List<String> segments = source.getPathSegments();
146	    try {
147	      return Integer.parseInt(segments.get(RESOURCE_ID_SEGMENT_INDEX));
148	    } catch (NumberFormatException e) {
149	      throw new IllegalArgumentException("Unrecognized Uri format: " + source, e);
150	    }
