219	  private static final class FrameworkConnectivityMonitorPreApi24
220	      implements FrameworkConnectivityMonitor {
221	    // Using AsyncTasks's executor is a hack. We need a background thread, but it's not trivial to
222	    // pass one through to this point. We could make a breaking API change, which upsets external
223	    // users. Or we could try to add an API to expose one of Glide's executors via the singleton,
224	    // but that could allow Glide's executors to be misused as general purpose executors. Given that
225	    // this code is deprecated anyway, using some pre-existing general purpose executor doesn't seem
226	    // wildly unreasonable.
227	    @Synthetic static final Executor EXECUTOR = AsyncTask.SERIAL_EXECUTOR;
228	    @Synthetic final Context context;
229	    @Synthetic final ConnectivityListener listener;
230	    private final GlideSupplier<ConnectivityManager> connectivityManager;
231	    // These are only manipulated serially, but the executor might use separate threads to do so,
232	    // so we use volatile.
233	    @Synthetic volatile boolean isConnected;
234	    @Synthetic volatile boolean isRegistered;
235	
236	    @Synthetic
237	    final BroadcastReceiver connectivityReceiver =
238	        new BroadcastReceiver() {
239	          @Override
240	          public void onReceive(@NonNull Context context, Intent intent) {
241	            onConnectivityChange();
242	          }
243	        };
244	
245	    FrameworkConnectivityMonitorPreApi24(
246	        Context context,
247	        GlideSupplier<ConnectivityManager> connectivityManager,
248	        ConnectivityListener listener) {
249	      this.context = context.getApplicationContext();
250	      this.connectivityManager = connectivityManager;
251	      this.listener = listener;
252	    }
253	
254	    @Override
255	    public boolean register() {
256	      EXECUTOR.execute(
257	          new Runnable() {
258	            @Override
259	            public void run() {
260	              // Initialize isConnected so that we notice the first time around when there's a
261	              // broadcast.
262	              // TODO(judds): This causes a race where:
263	              // 1. Connectivity is disconnected
264	              // 2. Register is called, but punted to a background thread and not run yet
265	              // 3. Some network requiring request is started, runs and fails due to connectivity
266	              // 4. Connectivity is re-established
267	              // 5. This code finally runs on the background thread.
268	              // In step 5, we'll think that we're currently connected and won't trigger a retry for
269	              // any previously failed requests.
270	              // In the long run it might be nice to define some explicit initialization step for
271	              // Glide where we do this and other expensive things on a background thread prior to
272	              // starting the first request. For now it seems better to just accept this race than
273	              // either take the latency hit of the IPC on the main thread, or try something like
274	              // always notifying all listeners once right after this logic runs just in case
275	              // something failed.
276	              isConnected = isConnected();
277	              try {
