279	                context.registerReceiver(
280	                    connectivityReceiver,
281	                    new IntentFilter(ConnectivityManager.CONNECTIVITY_ACTION));
282	                isRegistered = true;
283	              } catch (SecurityException e) {
284	                // See #1417, registering the receiver can throw SecurityException.
285	                if (Log.isLoggable(TAG, Log.WARN)) {
