300	      // circuit that by checking isConnected on this thread, we might leak a receiver.
301	      EXECUTOR.execute(
302	          new Runnable() {
303	            @Override
304	            public void run() {
305	              if (!isRegistered) {
306	                return;
307	              }
308	              isRegistered = false;
309	              context.unregisterReceiver(connectivityReceiver);
310	            }
311	          });
312	    }
