314	    @Synthetic
315	    void onConnectivityChange() {
316	      EXECUTOR.execute(
317	          new Runnable() {
318	            @Override
319	            public void run() {
320	              boolean wasConnected = isConnected;
321	              isConnected = isConnected();
322	              if (wasConnected != isConnected) {
