346	    @SuppressWarnings("WeakerAccess")
347	    @Synthetic
348	    // Permissions are checked in the factory instead.
349	    @SuppressLint("MissingPermission")
350	    boolean isConnected() {
351	      NetworkInfo networkInfo;
352	      try {
353	        networkInfo = connectivityManager.get().getActiveNetworkInfo();
