358	        if (Log.isLoggable(TAG, Log.WARN)) {
359	          Log.w(TAG, "Failed to determine connectivity status when connectivity changed", e);
360	        }
361	        // Default to true;
362	        return true;
363	      }
364	      return networkInfo != null && networkInfo.isConnected();
365	    }
