157	  public RequestManager get(@NonNull View view) {
158	    if (Util.isOnBackgroundThread()) {
159	      return get(view.getContext().getApplicationContext());
160	    }
161	
162	    Preconditions.checkNotNull(view);
163	    Preconditions.checkNotNull(
164	        view.getContext(), "Unable to obtain a request manager for a view without a Context");
165	    Activity activity = findActivity(view.getContext());
166	    // The view might be somewhere else, like a service.
167	    if (activity == null) {
168	      return get(view.getContext().getApplicationContext());
169	    }
170	
171	    // Support Fragments.
172	    // Although the user might have non-support Fragments attached to FragmentActivity, searching
173	    // for non-support Fragments is so expensive pre O and that should be rare enough that we
174	    // prefer to just fall back to the Activity directly.
175	    if (activity instanceof FragmentActivity) {
176	      Fragment fragment = findSupportFragment(view, (FragmentActivity) activity);
177	      return fragment != null ? get(fragment) : get((FragmentActivity) activity);
178	    }
179	
