183	
184	  private static void findAllSupportFragmentsWithViews(
185	      @Nullable Collection<Fragment> topLevelFragments, @NonNull Map<View, Fragment> result) {
186	    if (topLevelFragments == null) {
187	      return;
188	    }
189	    for (Fragment fragment : topLevelFragments) {
190	      // getFragment()s in the support FragmentManager may contain null values, see #1991.
191	      if (fragment == null || fragment.getView() == null) {
192	        continue;
193	      }
194	      result.put(fragment.getView(), fragment);
195	      findAllSupportFragmentsWithViews(fragment.getChildFragmentManager().getFragments(), result);
196	    }
197	  }
