199	  @Nullable
200	  private Fragment findSupportFragment(@NonNull View target, @NonNull FragmentActivity activity) {
201	    tempViewToSupportFragment.clear();
202	    findAllSupportFragmentsWithViews(
203	        activity.getSupportFragmentManager().getFragments(), tempViewToSupportFragment);
204	    Fragment result = null;
205	    View activityRoot = activity.findViewById(android.R.id.content);
206	    View current = target;
207	    while (!current.equals(activityRoot)) {
208	      result = tempViewToSupportFragment.get(current);
209	      if (result != null) {
210	        break;
211	      }
212	      if (current.getParent() instanceof View) {
213	        current = (View) current.getParent();
214	      } else {
215	        break;
216	      }
217	    }
218	
219	    tempViewToSupportFragment.clear();
220	    return result;
221	  }
