224	  private static Activity findActivity(@NonNull Context context) {
225	    if (context instanceof Activity) {
226	      return (Activity) context;
227	    } else if (context instanceof ContextWrapper) {
228	      return findActivity(((ContextWrapper) context).getBaseContext());
229	    } else {
230	      return null;
231	    }
232	  }
