6	import java.io.IOException;
7	import java.io.OutputStream;
8	
9	/**
10	 * An {@link OutputStream} implementation that recycles and re-uses {@code byte[]}s using the
11	 * provided {@link ArrayPool}.
12	 */
13	public final class BufferedOutputStream extends OutputStream {
14	  @NonNull private final OutputStream out;
15	  private byte[] buffer;
16	  private ArrayPool arrayPool;
17	  private int index;
18	
19	  public BufferedOutputStream(@NonNull OutputStream out, @NonNull ArrayPool arrayPool) {
20	    this(out, arrayPool, ArrayPool.STANDARD_BUFFER_SIZE_BYTES);
21	  }
22	
23	  @VisibleForTesting
24	  BufferedOutputStream(@NonNull OutputStream out, ArrayPool arrayPool, int bufferSize) {
25	    this.out = out;
26	    this.arrayPool = arrayPool;
27	    buffer = arrayPool.get(bufferSize, byte[].class);
28	  }
29	
30	  @Override
31	  public void write(int b) throws IOException {
32	    buffer[index++] = (byte) b;
33	    maybeFlushBuffer();
34	  }
35	
36	  @Override
37	  public void write(@NonNull byte[] b) throws IOException {
38	    write(b, 0, b.length);
39	  }
40	
41	  @Override
42	  public void write(@NonNull byte[] b, int initialOffset, int length) throws IOException {
43	    int writtenSoFar = 0;
44	    do {
45	      int remainingToWrite = length - writtenSoFar;
46	      int currentOffset = initialOffset + writtenSoFar;
47	      // If we still need to write at least the buffer size worth of bytes, we might as well do so
48	      // directly and avoid the overhead of copying to the buffer first.
49	      if (index == 0 && remainingToWrite >= buffer.length) {
50	        out.write(b, currentOffset, remainingToWrite);
51	        return;
52	      }
53	
54	      int remainingSpaceInBuffer = buffer.length - index;
55	      int totalBytesToWriteToBuffer = Math.min(remainingToWrite, remainingSpaceInBuffer);
56	
57	      System.arraycopy(b, currentOffset, buffer, index, totalBytesToWriteToBuffer);
58	
59	      index += totalBytesToWriteToBuffer;
60	      writtenSoFar += totalBytesToWriteToBuffer;
61	
62	      maybeFlushBuffer();
63	    } while (writtenSoFar < length);
64	  }
65	
66	  @Override
67	  public void flush() throws IOException {
68	    flushBuffer();
69	    out.flush();
70	  }
71	
72	  private void flushBuffer() throws IOException {
73	    if (index > 0) {
74	      out.write(buffer, 0, index);
75	      index = 0;
76	    }
77	  }
78	
79	  private void maybeFlushBuffer() throws IOException {
80	    if (index == buffer.length) {
81	      flushBuffer();
82	    }
83	  }
84	
85	  @Override
86	  public void close() throws IOException {
87	    try {
88	      flush();
89	    } finally {
90	      out.close();
91	    }
92	    release();
93	  }
94	
95	  private void release() {
96	    if (buffer != null) {
97	      arrayPool.put(buffer);
98	      buffer = null;
99	    }
100	  }
101	}
